// The application shell — routing, layout and error boundary ONLY.
import { Component, useEffect, useState } from "react";
import HomePage from "./routes/HomePage";
import BookPage from "./routes/BookPage";
import ManagePage from "./routes/ManagePage";
import VisitPage from "./routes/VisitPage";
import FarmPage from "./routes/FarmPage";
import { SiteLayout } from "./components/SiteLayout";

const ROUTES = {
  "/": HomePage,
  "/book": BookPage,
  "/manage": ManagePage,
  "/visit": VisitPage,
  "/farm": FarmPage,
};

export function navigateTo(path) {
  window.history.pushState({}, "", path);
  window.dispatchEvent(new PopStateEvent("popstate"));
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function useRoute() {
  const [path, setPath] = useState(() => window.location.pathname || "/");
  useEffect(() => {
    const onPop = () => setPath(window.location.pathname || "/");
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);
  return ROUTES[path] ? path : "/";
}

class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { error: null };
  }

  static getDerivedStateFromError(error) {
    return { error };
  }

  render() {
    if (this.state.error) {
      return (
        <div className="min-h-screen bg-background px-6 py-16 text-center text-foreground">
          <div className="mx-auto max-w-lg rounded-[2rem] border border-border bg-card p-8 shadow-sm">
            <p className="text-sm font-bold uppercase tracking-[0.25em] text-primary">Berry Brook Farm</p>
            <h1 className="mt-3 text-3xl font-semibold">The farm gate stuck for a moment.</h1>
            <p className="mt-3 text-muted-foreground">Reload the page to try again.</p>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

export default function App() {
  const path = useRoute();
  const Page = ROUTES[path] || HomePage;
  return (
    <ErrorBoundary>
      <SiteLayout currentPath={path} onNavigate={navigateTo}>
        <Page onNavigate={navigateTo} />
      </SiteLayout>
    </ErrorBoundary>
  );
}

