// Seeded in-app strawberry picking slots.
// These are product constants, not persisted records. Bookings reference a slot by `slotId`,
// while live availability is calculated from persisted active booking records.

const makeDate = (offsetDays) => {
  const date = new Date();
  date.setDate(date.getDate() + offsetDays);
  return date.toISOString().slice(0, 10);
};

export const SLOT_CAPACITY = 24;

export const PICKING_SLOTS = [
  { id: "row-a-morning", date: makeDate(1), startTime: "09:00", endTime: "10:30", capacity: 24, fieldRow: "Row A", note: "Best for families with little pickers" },
  { id: "row-b-midday", date: makeDate(1), startTime: "11:00", endTime: "12:30", capacity: 18, fieldRow: "Row B", note: "Sunny rows near the farm stand" },
  { id: "row-c-afternoon", date: makeDate(1), startTime: "14:00", endTime: "15:30", capacity: 20, fieldRow: "Row C", note: "Easy parking and shaded check-in" },
  { id: "row-d-morning", date: makeDate(2), startTime: "09:00", endTime: "10:30", capacity: 24, fieldRow: "Row D", note: "Cool morning picking" },
  { id: "row-e-midday", date: makeDate(2), startTime: "11:00", endTime: "12:30", capacity: 22, fieldRow: "Row E", note: "Great ripe fruit forecast" },
  { id: "row-f-afternoon", date: makeDate(2), startTime: "14:00", endTime: "15:30", capacity: 16, fieldRow: "Row F", note: "Limited ripe fruit" },
  { id: "row-g-morning", date: makeDate(3), startTime: "09:00", endTime: "10:30", capacity: 24, fieldRow: "Row G", note: "Weekend opening pick" },
  { id: "row-h-midday", date: makeDate(3), startTime: "11:00", endTime: "12:30", capacity: 24, fieldRow: "Row H", note: "Picnic lawn nearby" },
  { id: "row-i-afternoon", date: makeDate(3), startTime: "14:00", endTime: "15:30", capacity: 0, fieldRow: "Row I", note: "Field resting — full" },
];

export function listSeededSlots() {
  return PICKING_SLOTS.map((slot) => ({ ...slot }));
}

export function getSeededSlot(slotId) {
  const slot = PICKING_SLOTS.find((item) => item.id === slotId);
  return slot ? { ...slot } : null;
}

export function listAvailableDates() {
  return Array.from(new Set(PICKING_SLOTS.map((slot) => slot.date))).sort();
}

export function listSlotsForDate(date) {
  return PICKING_SLOTS.filter((slot) => slot.date === date).map((slot) => ({ ...slot }));
}

