import { db } from "../lib/backend";
import { ensureVisitorSession } from "../lib/visitorSession";
import { getSeededSlot, listSeededSlots, listSlotsForDate } from "./slots";

const bookingEntity = () => db.entity("booking");
const ACTIVE_STATUS = "active";
const CANCELLED_STATUS = "cancelled";

function unwrapBooking(row) {
  if (!row) return null;
  return { id: row.id, created_at: row.created_at, ...(row.data || {}) };
}

function normaliseEmail(email) {
  return String(email || "").trim().toLowerCase();
}

function visitorCount(booking) {
  return Number(booking?.adults || 0) + Number(booking?.children || 0);
}

function makeReference() {
  const letters = "ABCDEFGHJKLMNPQRSTUVWXYZ";
  const pick = () => letters[Math.floor(Math.random() * letters.length)];
  const number = Math.floor(1000 + Math.random() * 9000);
  return `BBF-${pick()}${pick()}-${number}`;
}

function requireBookingFields(input) {
  const adults = Number(input.adults || 0);
  const children = Number(input.children || 0);
  if (!input.slotId) throw new Error("Choose a picking slot before confirming your booking.");
  if (!Number.isInteger(adults) || adults < 1) throw new Error("At least one adult is required for a picking pass.");
  if (!Number.isInteger(children) || children < 0) throw new Error("Children count cannot be negative.");
  if (!String(input.customerName || "").trim()) throw new Error("Customer name is required.");
  if (!/^\S+@\S+\.\S+$/.test(normaliseEmail(input.email))) throw new Error("A valid email address is required.");
  if (!String(input.phone || "").trim()) throw new Error("Phone number is required.");
  return { adults, children };
}

async function ensureSession() {
  await ensureVisitorSession();
}

export async function listBookings(options = {}) {
  await ensureSession();
  const rows = await bookingEntity().list(options);
  return rows.map(unwrapBooking).filter(Boolean);
}

export async function listActiveBookingsForSlot(slotId) {
  if (!slotId) return [];
  const bookings = await listBookings({ filters: { slotId }, limit: 500 });
  return bookings.filter((booking) => booking.status === ACTIVE_STATUS);
}

export async function getSlotAvailability(slotId) {
  const slot = getSeededSlot(slotId);
  if (!slot) throw new Error("That picking slot is no longer available.");
  const activeBookings = await listActiveBookingsForSlot(slotId);
  const reserved = activeBookings.reduce((sum, booking) => sum + visitorCount(booking), 0);
  const remaining = Math.max(0, Number(slot.capacity || 0) - reserved);
  return {
    ...slot,
    reserved,
    remaining,
    isFull: remaining <= 0,
    activeBookings,
  };
}

export async function listSlotsWithAvailability(date) {
  await ensureSession();
  const slots = date ? listSlotsForDate(date) : listSeededSlots();
  const activeBookings = await listBookings({ limit: 500 });
  return slots.map((slot) => {
    const reserved = activeBookings
      .filter((booking) => booking.slotId === slot.id && booking.status === ACTIVE_STATUS)
      .reduce((sum, booking) => sum + visitorCount(booking), 0);
    const remaining = Math.max(0, Number(slot.capacity || 0) - reserved);
    return { ...slot, reserved, remaining, isFull: remaining <= 0 };
  });
}

export async function createBooking(input) {
  await ensureSession();
  const { adults, children } = requireBookingFields(input);
  const slot = getSeededSlot(input.slotId);
  if (!slot) throw new Error("Choose one of the seeded Berry Brook Farm picking slots.");

  const availability = await getSlotAvailability(slot.id);
  const partySize = adults + children;
  if (partySize > availability.remaining) {
    throw new Error(`Only ${availability.remaining} ${availability.remaining === 1 ? "place is" : "places are"} left for this slot.`);
  }

  const now = new Date().toISOString();
  const booking = {
    reference: String(input.reference || makeReference()).trim().toUpperCase(),
    slotId: slot.id,
    date: slot.date,
    startTime: slot.startTime,
    endTime: slot.endTime,
    adults,
    children,
    customerName: String(input.customerName).trim(),
    email: normaliseEmail(input.email),
    phone: String(input.phone).trim(),
    status: ACTIVE_STATUS,
    createdAt: now,
  };

  const row = await bookingEntity().create(booking);
  return unwrapBooking(row);
}

export async function findBookingByReferenceAndEmail(reference, email) {
  await ensureSession();
  const cleanReference = String(reference || "").trim().toUpperCase();
  const cleanEmail = normaliseEmail(email);
  if (!cleanReference || !cleanEmail) return null;
  const rows = await bookingEntity().list({ filters: { reference: cleanReference }, limit: 20 });
  const match = rows.map(unwrapBooking).find((booking) => normaliseEmail(booking.email) === cleanEmail);
  return match || null;
}

export async function cancelBooking({ reference, email } = {}) {
  await ensureSession();
  const booking = await findBookingByReferenceAndEmail(reference, email);
  if (!booking) throw new Error("We could not find a booking for that reference and email.");
  if (booking.status === CANCELLED_STATUS) return booking;

  const { id, created_at: _createdAtRow, ...bookingData } = booking;
  const updated = {
    ...bookingData,
    status: CANCELLED_STATUS,
    cancelledAt: new Date().toISOString(),
  };
  const row = await bookingEntity().update(id, updated);
  return unwrapBooking(row);
}

export async function safeListBookings(options = {}) {
  try {
    return await listBookings(options);
  } catch {
    return [];
  }
}

src/lib/devReporter.js:
// Dev-only runtime error reporter — the preview side of the shell's "Fix it" loop.
//
// When the app runs inside the Buildr101 preview iframe (vite dev), uncaught errors and
// unhandled promise rejections are posted to the parent shell, which shows a "Fix it"
// button that feeds the error back into the builder. Absent from production builds
// (import.meta.env.DEV guard) and inert when not iframed. Error text only — no app data.

if (import.meta.env.DEV && typeof window !== "undefined" && window.parent !== window) {
  const seen = new Set();
  let sent = 0;

  const report = (message, stack) => {
    const key = String(message).slice(0, 200);
    if (seen.has(key) || sent >= 5) return;
    seen.add(key);
    sent += 1;
    try {
      window.parent.postMessage(
        {
          __buildr: "runtime-error",
          message: String(message).slice(0, 500),
          stack: String(stack || "").slice(0, 2000),
        },
        "*"
      );
    } catch {
      /* parent gone — nothing to do */
    }
  };

  window.addEventListener("error", (e) => {
    report(e.message || e.error?.message || "Unknown error", e.error?.stack);
  });
  window.addEventListener("unhandledrejection", (e) => {
    const r = e.reason;
    report((r && (r.message || String(r))) || "Unhandled promise rejection", r && r.stack);
  });

  // ── Visual edits: select-mode bridge ─────────────────────────────────────────────────────
  // The shell toggles select mode with { __buildr: "select-mode", on }. While on, hovering
  // outlines elements and a click (captured before the app's own handlers) posts the element
  // back as { __buildr: "element-selected", tag, text, outerHTML, path } and exits the mode.
  let selecting = false;
  let hoverEl = null;
  let hoverOutline = "";

  const clearHover = () => {
    if (hoverEl) { hoverEl.style.outline = hoverOutline; hoverEl = null; hoverOutline = ""; }
  };
  const exitSelect = () => { selecting = false; clearHover(); document.documentElement.style.cursor = ""; };

  // Short structural path (up to 5 ancestors) so the model can locate the element in source.
  const cssPath = (el) => {
    const parts = [];
    let node = el;
    while (node && node.nodeType === 1 && parts.length < 5 && node.tagName !== "HTML") {
      let part = node.tagName.toLowerCase();
      if (node.id) { parts.unshift(`${part}#${node.id}`); break; }
      const parent = node.parentElement;
      if (parent) {
        const same = Array.from(parent.children).filter((c) => c.tagName === node.tagName);
        if (same.length > 1) part += `:nth-of-type(${same.indexOf(node) + 1})`;
      }
      parts.unshift(part);
      node = parent;
    }
    return parts.join(" > ");
  };

  window.addEventListener("message", (e) => {
    if (e.source !== window.parent) return;
    const d = e.data;
    if (!d || d.__buildr !== "select-mode") return;
    if (d.on) { selecting = true; document.documentElement.style.cursor = "crosshair"; }
    else exitSelect();
    // ACK so the shell can confirm the bridge is live in this preview (old trees lack it).
    try { window.parent.postMessage({ __buildr: "select-mode-ack", on: !!d.on }, "*"); } catch {}
  });

  document.addEventListener("mouseover", (e) => {
    if (!selecting || !(e.target instanceof Element)) return;
    clearHover();
    hoverEl = e.target;
    hoverOutline = hoverEl.style.outline;
    hoverEl.style.outline = "2px solid #f59e0b";
  }, true);

  document.addEventListener("click", (e) => {
    if (!selecting || !(e.target instanceof Element)) return;
    e.preventDefault();
    e.stopPropagation();
    const el = e.target;
    clearHover();
    try {
      window.parent.postMessage({
        __buildr: "element-selected",
        tag: el.tagName.toLowerCase(),
        text: (el.textContent || "").trim().slice(0, 120),
        outerHTML: el.outerHTML.slice(0, 600),
        path: cssPath(el),
      }, "*");
    } catch { /* parent gone */ }
    exitSelect();
  }, true);
}

