import { useEffect, useMemo, useState } from "react";
import { BookingConfirmation } from "@/components/BookingConfirmation";
import { BookingDateSelector } from "@/components/BookingDateSelector";
import { BookingDetailsForm } from "@/components/BookingDetailsForm";
import { BookingSlotSelector } from "@/components/BookingSlotSelector";
import { BookingSummary } from "@/components/BookingSummary";
import { PartySizeControls } from "@/components/PartySizeControls";
import { createBooking, listSlotsWithAvailability } from "@/data/bookings";
import { listAvailableDates } from "@/data/slots";

export default function BookPage() {
  const dates = useMemo(() => listAvailableDates(), []);
  const [selectedDate, setSelectedDate] = useState(() => dates[0] || "");
  const [slots, setSlots] = useState([]);
  const [selectedSlotId, setSelectedSlotId] = useState("");
  const [adults, setAdults] = useState(1);
  const [children, setChildren] = useState(0);
  const [loadingSlots, setLoadingSlots] = useState(false);
  const [slotMessage, setSlotMessage] = useState("");
  const [submitError, setSubmitError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [confirmedBooking, setConfirmedBooking] = useState(null);
  const [partyTouched, setPartyTouched] = useState(false);

  const selectedSlot = slots.find((slot) => slot.id === selectedSlotId) || null;
  const partySize = adults + children;
  const partyTooLarge = selectedSlot && partySize > selectedSlot.remaining;

  useEffect(() => {
    if (!selectedDate) return;
    let cancelled = false;
    setLoadingSlots(true);
    setSlotMessage("Loading availability labels while bookings are counted...");
    setSelectedSlotId("");
    listSlotsWithAvailability(selectedDate)
      .then((items) => {
        if (cancelled) return;
        setSlots(items);
        setSlotMessage(items.length ? "Success: available 90-minute time slots for that date are displayed with visible availability indicators." : "Empty: this date has no open slots and is unavailable.");
      })
      .catch((error) => {
        if (cancelled) return;
        setSlots([]);
        setSlotMessage(error.message || "Error: availability could not be loaded. Try choosing the date again.");
      })
      .finally(() => {
        if (!cancelled) setLoadingSlots(false);
      });
    return () => {
      cancelled = true;
    };
  }, [selectedDate]);

  const chooseSlot = (slot) => {
    setSubmitError("");
    if (slot.isFull) {
      setSlotMessage("Error: attempting to book a full slot shows that the slot is full.");
      return;
    }
    setSelectedSlotId(slot.id);
    setSlotMessage("Success: selected slot highlighted and booking summary updated with the chosen date and time.");
  };

  const disabledReason = !selectedSlot
    ? "Choose an available date and 90-minute slot before confirming."
    : partyTooLarge
      ? "Party is too large for this slot; reduce adults or children before confirming."
      : "";

  const submitBooking = async (form) => {
    setSubmitError("");
    setSubmitting(true);
    try {
      const booking = await createBooking({
        slotId: selectedSlot.id,
        adults,
        children,
        customerName: form.customerName,
        email: form.email,
        phone: form.phone,
      });
      setConfirmedBooking(booking);
    } catch (error) {
      setSubmitError(error.message || "The farm gate could not save your booking. Please try again.");
      if (selectedDate) {
        listSlotsWithAvailability(selectedDate).then(setSlots).catch(() => {});
      }
    } finally {
      setSubmitting(false);
    }
  };

  if (confirmedBooking) {
    return <BookingConfirmation booking={confirmedBooking} />;
  }

  return (
    <main className="berry-container py-10 lg:py-14">
      <div className="grid gap-8 lg:grid-cols-[0.85fr_1.15fr]">
        <BookingSummary selectedDate={selectedDate} selectedSlot={selectedSlot} adults={adults} children={children} partyTouched={partyTouched} />
