          <BookingSlotSelector
            selectedDate={selectedDate}
            slots={slots}
            selectedSlotId={selectedSlotId}
            onSelectSlot={chooseSlot}
            loading={loadingSlots}
            error={slotMessage.startsWith("Error") ? slotMessage : ""}
          />
          {slotMessage && !slotMessage.startsWith("Error") && (
            <p className="rounded-2xl bg-background p-4 text-sm font-bold text-muted-foreground" aria-live="polite">{slotMessage}</p>
          )}
          <PartySizeControls
            adults={adults}
            children={children}
            onAdultsChange={(value) => { setPartyTouched(true); setAdults(value); }}
            onChildrenChange={(value) => { setPartyTouched(true); setChildren(value); }}
            selectedSlot={selectedSlot}
          />
          {submitError && <p className="rounded-2xl border border-destructive/30 bg-destructive/10 p-4 text-sm font-bold text-destructive" aria-live="polite">{submitError}</p>}
          <BookingDetailsForm disabled={!selectedSlot || partyTooLarge} disabledReason={disabledReason} onSubmit={submitBooking} submitting={submitting} />
        </div>
      </div>
    </main>
  );
}

