import { useState } from "react";
import { Menu, Sprout, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

const NAV_ITEMS = [
  { path: "/", label: "Home" },
  { path: "/book", label: "Book Now" },
  { path: "/visit", label: "Plan Your Visit" },
  { path: "/farm", label: "Our Farm" },
  { path: "/manage", label: "Manage booking" },
];

export function SiteLayout({ children, currentPath, onNavigate }) {
  const [open, setOpen] = useState(false);

  const go = (path) => {
    setOpen(false);
    onNavigate(path);
  };

  return (
    <div className="min-h-screen bg-background text-foreground">
      <header className="sticky top-0 z-40 border-b border-border/70 bg-background/95 backdrop-blur">
        <div className="berry-container flex min-h-20 items-center justify-between gap-4 py-3">
          <button
            type="button"
            onClick={() => go("/")}
            className="group flex min-w-0 items-center gap-3 text-left"
            aria-label="Berry Brook Farm home"
          >
            <span className="grid h-11 w-11 shrink-0 place-items-center rounded-full bg-primary text-primary-foreground shadow-[0_4px_0_rgba(58,36,25,0.18)] transition-transform group-hover:-rotate-6">
              <Sprout className="h-5 w-5" />
            </span>
            <span className="min-w-0">
              <span className="block font-display text-xl font-semibold leading-none sm:text-2xl">Berry Brook</span>
              <span className="block text-xs font-bold uppercase tracking-[0.22em] text-muted-foreground">Strawberry farm</span>
            </span>
          </button>

          <nav className="hidden items-center rounded-full border border-border bg-card/80 p-1 shadow-sm lg:flex" aria-label="Primary navigation">
            {NAV_ITEMS.map((item) => (
              <button
                key={item.path}
                type="button"
                onClick={() => go(item.path)}
                className={cn(
                  "rounded-full px-4 py-2 text-sm font-bold text-muted-foreground transition hover:bg-muted hover:text-foreground",
                  currentPath === item.path && "bg-secondary text-secondary-foreground shadow-sm"
                )}
              >
                {item.label}
              </button>
            ))}
          </nav>

          <div className="flex items-center gap-2">
            <Button className="hidden bg-primary text-primary-foreground shadow-[0_4px_0_hsl(var(--destructive))] hover:bg-primary/90 sm:inline-flex" onClick={() => go("/book")}>Book a slot</Button>
            <Button variant="outline" size="icon" className="lg:hidden" onClick={() => setOpen((value) => !value)} aria-label={open ? "Close navigation" : "Open navigation"} aria-expanded={open}>
              {open ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
            </Button>
          </div>
        </div>

        {open && (
          <div className="border-t border-border bg-card lg:hidden">
            <div className="berry-container py-4">
              <div className="runner-divider" aria-hidden="true" />
              <div className="grid gap-2">
                {NAV_ITEMS.map((item) => (
                  <button
                    key={item.path}
                    type="button"
                    onClick={() => go(item.path)}
                    className={cn(
                      "rounded-2xl px-4 py-3 text-left font-bold text-muted-foreground",
                      currentPath === item.path ? "bg-secondary text-secondary-foreground" : "bg-background"
                    )}
                  >
                    {item.label}
                  </button>
                ))}
                <p className="rounded-2xl bg-secondary/30 p-3 text-sm font-bold text-secondary-foreground" aria-live="polite">Success: mobile menu is open with usable navigation links and will close after selection.</p>
                <Button className="mt-2 bg-primary text-primary-foreground" onClick={() => go("/book")}>Book a picking slot</Button>
              </div>
            </div>
          </div>
        )}
      </header>

      {children}

      <footer className="mt-20 border-t border-border bg-card/80">
        <div className="berry-container grid gap-8 py-10 md:grid-cols-[1.3fr_0.7fr_0.7fr]">
          <div>
            <p className="font-display text-3xl font-semibold">Berry Brook Farm</p>
            <p className="mt-3 max-w-md text-sm leading-6 text-muted-foreground">
              A family strawberry field with timed picking, picnic benches, and warm on-arrival guidance for small hands and first-time pickers.
            </p>
          </div>
          <div>
            <p className="text-sm font-bold uppercase tracking-[0.2em] text-primary">Visit</p>
            <p className="mt-3 text-sm text-muted-foreground">Mayfield Lane, Brook Hollow<br />Open seasonally, 9am–5pm</p>
          </div>
          <div>
            <p className="text-sm font-bold uppercase tracking-[0.2em] text-primary">Need help?</p>
            <p className="mt-3 text-sm text-muted-foreground">Bring your booking reference to the red farm gate. On-arrival payment only.</p>
          </div>
        </div>
      </footer>
    </div>
  );
}

