function formatDate(date) {
  if (!date) return "Choose a date";
  return new Intl.DateTimeFormat("en", { weekday: "long", month: "long", day: "numeric" }).format(new Date(`${date}T12:00:00`));
}

export function BookingSummary({ selectedDate, selectedSlot, adults, children, partyTouched }) {
  const partySize = Number(adults) + Number(children);
  const remainingAfterParty = selectedSlot ? selectedSlot.remaining - partySize : null;
  const tooLarge = selectedSlot && partySize > selectedSlot.remaining;

  return (
    <aside className="paper-panel rounded-[2rem] p-6 lg:sticky lg:top-28 lg:self-start" aria-live="polite">
      <div className="rounded-2xl border-2 border-primary bg-card px-4 py-3 text-center shadow-lg">
        <p className="text-xs font-black uppercase tracking-[0.22em] text-primary">Picking today</p>
        <p className="mt-1 font-display text-2xl font-semibold">Limited ripe fruit</p>
      </div>
      <h1 className="mt-6 text-4xl font-semibold sm:text-5xl">Book Now</h1>
      <p className="mt-4 leading-7 text-muted-foreground">Build your paper picking pass step by step. Payment is on arrival at the red gate.</p>

      <div className="mt-6 space-y-3 rounded-[1.5rem] bg-background p-4">
        <p className="text-sm font-bold uppercase tracking-[0.18em] text-primary">{selectedSlot ? "Booking summary updated" : "Picking pass draft"}</p>
        <div>
          <p className="text-xs font-bold uppercase text-muted-foreground">Chosen date</p>
          <p className="font-display text-2xl font-semibold">{formatDate(selectedDate)}</p>
        </div>
        <div>
          <p className="text-xs font-bold uppercase text-muted-foreground">Chosen time</p>
          <p className="font-display text-2xl font-semibold">{selectedSlot ? `${selectedSlot.startTime}–${selectedSlot.endTime}` : "Choose a slot"}</p>
        </div>
        {partyTouched && (
          <div>
            <p className="text-xs font-bold uppercase text-muted-foreground">Selected visitor count</p>
            <p className="font-display text-2xl font-semibold">{partySize} {partySize === 1 ? "picker" : "pickers"}</p>
          </div>
        )}
        {selectedSlot && (
          <p className={tooLarge ? "rounded-xl bg-destructive/10 p-3 text-sm font-bold text-destructive" : "rounded-xl bg-secondary/30 p-3 text-sm font-bold text-secondary-foreground"}>
            {tooLarge
              ? `Party is too large for this slot: ${selectedSlot.remaining} ${selectedSlot.remaining === 1 ? "space remains" : "spaces remain"}.`
              : `After your selected count, ${remainingAfterParty} ${remainingAfterParty === 1 ? "space" : "spaces"} will remain in ${selectedSlot.fieldRow}.`}
          </p>
        )}
      </div>
    </aside>
  );
}

