import { db } from "../lib/backend";
import { ensureVisitorSession } from "../lib/visitorSession";

const subscriberEntity = () => db.entity("newsletterSubscriber");

function unwrapSubscriber(row) {
  if (!row) return null;
  return { id: row.id, created_at: row.created_at, ...(row.data || {}) };
}

function normaliseEmail(email) {
  return String(email || "").trim().toLowerCase();
}

export function validateNewsletterEmail(email) {
  return /^\S+@\S+\.\S+$/.test(normaliseEmail(email));
}

export async function createNewsletterSubscriber(email) {
  await ensureVisitorSession();
  const cleanEmail = normaliseEmail(email);
  if (!validateNewsletterEmail(cleanEmail)) {
    throw new Error("Enter a valid email address to join Berry Brook Farm updates.");
  }

  const row = await subscriberEntity().create({
    email: cleanEmail,
    createdAt: new Date().toISOString(),
  });
  return unwrapSubscriber(row);
}

export async function listNewsletterSubscribers(options = {}) {
  await ensureVisitorSession();
  const rows = await subscriberEntity().list(options);
  return rows.map(unwrapSubscriber).filter(Boolean);
}

export async function safeListNewsletterSubscribers(options = {}) {
  try {
    return await listNewsletterSubscribers(options);
  } catch {
    return [];
  }
}

