import { Button } from "@/components/ui/button";

function Counter({ label, value, min, onChange }) {
  return (
    <div className="rounded-2xl border border-border bg-background p-4">
      <p className="text-sm font-bold text-muted-foreground">{label}</p>
      <div className="mt-3 flex items-center justify-between gap-3">
        <Button type="button" variant="outline" size="icon" onClick={() => onChange(Math.max(min, value - 1))} disabled={value <= min} aria-label={`Decrease ${label.toLowerCase()}`}>−</Button>
        <span className="font-display text-4xl font-semibold" aria-live="polite">{value}</span>
        <Button type="button" variant="outline" size="icon" onClick={() => onChange(value + 1)} aria-label={`Increase ${label.toLowerCase()}`}>+</Button>
      </div>
    </div>
  );
}

export function PartySizeControls({ adults, children, onAdultsChange, onChildrenChange, selectedSlot }) {
  const partySize = adults + children;
  const tooLarge = selectedSlot && partySize > selectedSlot.remaining;
  return (
    <section className="paper-panel rounded-[2rem] p-5 sm:p-6" aria-labelledby="party-step-title">
      <p className="text-sm font-bold uppercase tracking-[0.25em] text-primary">Step 3</p>
      <h2 id="party-step-title" className="mt-2 text-3xl font-semibold">Choose adults and children</h2>
      <p className="mt-3 text-sm leading-6 text-muted-foreground">At least one adult is required. Children are welcome in every row.</p>
      <div className="mt-5 grid gap-3 sm:grid-cols-2">
        <Counter label="Adults" value={adults} min={1} onChange={onAdultsChange} />
        <Counter label="Children" value={children} min={0} onChange={onChildrenChange} />
      </div>
      {selectedSlot && (
        <p className={tooLarge ? "mt-4 rounded-2xl border border-destructive/30 bg-destructive/10 p-4 text-sm font-bold text-destructive" : "mt-4 rounded-2xl bg-secondary/30 p-4 text-sm font-bold text-secondary-foreground"}>
          {tooLarge
            ? "Validation: party size cannot exceed remaining spaces for the selected slot. Reduce your selected visitor count to continue."
            : `Validation message cleared: booking can continue. Selected count is ${partySize}, leaving ${selectedSlot.remaining - partySize} spaces for this slot.`}
        </p>
      )}
    </section>
  );
}

