import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export function BookingDetailsForm({ disabled, disabledReason, onSubmit, submitting }) {
  const [form, setForm] = useState({ customerName: "", email: "", phone: "", terms: false });
  const [validation, setValidation] = useState("");

  const update = (field, value) => {
    setValidation("");
    setForm((current) => ({ ...current, [field]: value }));
  };

  const submit = (event) => {
    event.preventDefault();
    if (disabled) {
      setValidation(disabledReason || "Choose a date and slot before confirming.");
      return;
    }
    if (!form.customerName.trim()) return setValidation("Enter the lead picker name.");
    if (!/^\S+@\S+\.\S+$/.test(form.email.trim())) return setValidation("Enter a valid email address for your picking pass.");
    if (!form.phone.trim()) return setValidation("Enter a phone number in case the farm needs to reach you.");
    if (!form.terms) return setValidation("Accept the farm terms before we make your picking pass.");
    onSubmit(form);
  };

  return (
    <section className="paper-panel rounded-[2rem] p-5 sm:p-6" aria-labelledby="details-step-title">
      <p className="text-sm font-bold uppercase tracking-[0.25em] text-primary">Step 4</p>
      <h2 id="details-step-title" className="mt-2 text-3xl font-semibold">Booking details form</h2>
      <form className="mt-5 grid gap-4" onSubmit={submit}>
        <div className="grid gap-2">
          <Label htmlFor="customerName">Name</Label>
          <Input id="customerName" value={form.customerName} onChange={(event) => update("customerName", event.target.value)} placeholder="Sam Fielding" />
        </div>
        <div className="grid gap-2 sm:grid-cols-2">
          <div className="grid gap-2">
            <Label htmlFor="email">Email</Label>
            <Input id="email" type="email" value={form.email} onChange={(event) => update("email", event.target.value)} placeholder="sam@example.com" />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="phone">Phone</Label>
            <Input id="phone" value={form.phone} onChange={(event) => update("phone", event.target.value)} placeholder="07123 456789" />
          </div>
        </div>
        <label className="flex gap-3 rounded-2xl bg-background p-4 text-sm leading-6">
          <Checkbox checked={form.terms} onCheckedChange={(checked) => update("terms", checked === true)} />
          <span>I accept the farm terms: supervise children, follow row markers, and pay for picked fruit on arrival.</span>
        </label>
        {(validation || disabledReason) && (
          <p className="rounded-2xl border border-destructive/30 bg-destructive/10 p-4 text-sm font-bold text-destructive" aria-live="polite">
            {validation || disabledReason}
          </p>
        )}
        <Button type="submit" size="lg" disabled={submitting || disabled} className="bg-primary text-primary-foreground shadow-[0_5px_0_hsl(var(--destructive))]">
          {submitting ? "Making your picking pass..." : "Confirm picking slot"}
        </Button>
      </form>
    </section>
  );
}

