import { CalendarDays } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

function formatDate(date) {
  return new Intl.DateTimeFormat("en", { weekday: "short", month: "short", day: "numeric" }).format(new Date(`${date}T12:00:00`));
}

export function BookingDateSelector({ dates, selectedDate, onSelectDate, loading }) {
  const restDate = (() => {
    const last = dates[dates.length - 1];
    if (!last) return null;
    const date = new Date(`${last}T12:00:00`);
    date.setDate(date.getDate() + 1);
    return date.toISOString().slice(0, 10);
  })();

  return (
    <section className="paper-panel rounded-[2rem] p-5 sm:p-6" aria-labelledby="date-step-title">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-sm font-bold uppercase tracking-[0.25em] text-primary">Step 1</p>
          <h2 id="date-step-title" className="mt-2 text-3xl font-semibold">First step: choosing a picking date</h2>
        </div>
        <Badge className="bg-secondary text-secondary-foreground hover:bg-secondary">Picking today</Badge>
      </div>
      <p className="mt-3 text-sm leading-6 text-muted-foreground">
        Pick a harvest day first. We will count row capacity after you choose a date.
      </p>

      <div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
        {loading && Array.from({ length: 3 }).map((_, index) => (
          <div key={index} className="h-28 animate-pulse rounded-2xl border border-border bg-background/70" />
        ))}
        {!loading && dates.map((date) => {
          const active = selectedDate === date;
          return (
            <button
              key={date}
              type="button"
              onClick={() => onSelectDate(date)}
              aria-selected={active}
              className={cn(
                "rounded-2xl border bg-background p-4 text-left transition hover:-translate-y-0.5 hover:border-primary/60",
                active && "border-primary bg-muted shadow-[0_5px_0_hsl(var(--primary)/0.25)]"
              )}
            >
              <CalendarDays className="h-5 w-5 text-primary" />
              <p className="mt-3 font-display text-2xl font-semibold">{formatDate(date)}</p>
              <p className="mt-1 text-sm font-bold text-muted-foreground">Availability labels appear in the time-slot cards for this harvest day.</p>
              {active && <p className="mt-2 text-sm font-black text-primary">Selected picking date</p>}
            </button>
          );
        })}
        {!loading && restDate && (
          <div className="rounded-2xl border border-dashed border-border bg-background/60 p-4 opacity-80">
            <CalendarDays className="h-5 w-5 text-muted-foreground" />
            <p className="mt-3 font-display text-2xl font-semibold">{formatDate(restDate)}</p>
            <p className="mt-1 text-sm font-bold text-destructive">Unavailable — no open slots</p>
            <p className="mt-2 text-xs leading-5 text-muted-foreground">The fields rest while berries ripen for the next picking day.</p>
          </div>
        )}
      </div>
    </section>
  );
}

