import { Clock, Sprout } from "lucide-react";
import { cn } from "@/lib/utils";

function labelFor(slot) {
  if (slot.isFull) return "Full";
  if (slot.remaining <= 4) return `Limited — ${slot.remaining} ${slot.remaining === 1 ? "space" : "spaces"} left`;
  return `${slot.remaining} places left`;
}

export function BookingSlotSelector({ selectedDate, slots, selectedSlotId, onSelectSlot, loading, error }) {
  return (
    <section className="paper-panel rounded-[2rem] p-5 sm:p-6" aria-labelledby="slot-step-title">
      <div className="flex items-start justify-between gap-4">
        <div>
          <p className="text-sm font-bold uppercase tracking-[0.25em] text-primary">Step 2</p>
          <h2 id="slot-step-title" className="mt-2 text-3xl font-semibold">
            {selectedDate ? "Choose an available 90-minute time slot" : "Field-row slot selector"}
          </h2>
        </div>
        <Sprout className="mt-2 h-6 w-6 text-secondary-foreground" />
      </div>

      {!selectedDate && (
        <div className="mt-5 rounded-2xl border border-dashed border-border bg-background p-5 text-sm text-muted-foreground">
          Choose a picking date to load available 90-minute time slots and field-row availability indicators.
        </div>
      )}

      {selectedDate && loading && (
        <div className="mt-5 grid gap-3" aria-live="polite">
          {Array.from({ length: 3 }).map((_, index) => (
            <div key={index} className="h-24 animate-pulse rounded-2xl border border-border bg-background/70">
              <span className="sr-only">Loading availability labels while bookings are counted</span>
            </div>
          ))}
        </div>
      )}

      {error && <p className="mt-4 rounded-2xl border border-destructive/30 bg-destructive/10 p-4 text-sm font-bold text-destructive">{error}</p>}

      {selectedDate && !loading && slots.length === 0 && (
        <div className="mt-5 rounded-2xl border border-dashed border-border bg-background p-5">
          <p className="font-bold text-destructive">Unavailable — no open slots for this date.</p>
          <p className="mt-2 text-sm text-muted-foreground">Please choose another harvest day from the date cards.</p>
        </div>
      )}

      {selectedDate && !loading && slots.length > 0 && (
        <div className="mt-5 grid gap-3">
          {slots.map((slot) => {
            const selected = selectedSlotId === slot.id;
            return (
              <button
                key={slot.id}
                type="button"
                aria-selected={selected}
                aria-disabled={slot.isFull}
                onClick={() => onSelectSlot(slot)}
                className={cn(
                  "group rounded-[1.5rem] border bg-background p-4 text-left transition hover:border-primary/70",
                  selected && "border-primary bg-muted shadow-[0_6px_0_hsl(var(--primary)/0.22)]",
                  slot.isFull && "border-dashed opacity-75"
                )}
              >
                <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                  <div className="flex items-center gap-4">
                    <span className={cn("h-5 w-5 rounded-full border-2 border-card", slot.isFull ? "bg-destructive" : "bg-secondary")} />
                    <div>
                      <p className="font-display text-3xl font-semibold">{slot.startTime}–{slot.endTime}</p>
                      <p className="mt-1 text-sm text-muted-foreground">{slot.fieldRow} · {slot.note}</p>
                    </div>
                  </div>
                  <div className="rounded-full bg-card px-4 py-2 text-sm font-black text-primary">
                    {labelFor(slot)}
                  </div>
                </div>
                <div className="mt-4 flex items-center gap-2 rounded-full bg-secondary/30 px-4 py-2 text-sm font-bold text-secondary-foreground">
                  <Clock className="h-4 w-4" /> Available 90-minute time slot for this date
                </div>
                {selected && <p className="mt-3 text-sm font-black text-primary">Selected slot highlighted — booking summary updated with this chosen date and time.</p>}
                {slot.isFull && <p className="mt-3 text-sm font-bold text-destructive">Full — this slot is full and cannot be selected.</p>}
              </button>
            );
          })}
        </div>
      )}
    </section>
  );
}

src/components/ManageBookingLookup.jsx:
import { useState } from "react";
import { Search } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cancelBooking, findBookingByReferenceAndEmail } from "@/data/bookings";

function formatDate(date) {
  return date ? new Intl.DateTimeFormat("en", { weekday: "long", month: "long", day: "numeric" }).format(new Date(`${date}T12:00:00`)) : "";
}

export function ManageBookingLookup() {
  const [reference, setReference] = useState("");
  const [email, setEmail] = useState("");
  const [booking, setBooking] = useState(null);
  const [loading, setLoading] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [confirmingCancel, setConfirmingCancel] = useState(false);
  const [message, setMessage] = useState("Enter your booking reference and email to display the same reservation details after a reload.");

  const lookup = async (event) => {
    event.preventDefault();
    setBooking(null);
    if (!reference.trim() || !/^\S+@\S+\.\S+$/.test(email.trim())) {
      setMessage("Validation: enter a booking reference and a valid email address.");
      return;
    }
    setLoading(true);
    setMessage("Loading reservation details from the farm booking records...");
    try {
      const found = await findBookingByReferenceAndEmail(reference, email);
      if (!found) {
        setMessage("Empty state: no reservation details are linked to that reference and email.");
      } else {
        setBooking(found);
        setMessage("Success: the same reservation details are displayed after the reload.");
      }
    } catch (error) {
      setMessage(error.message || "Error: the booking lookup could not load right now.");
    } finally {
      setLoading(false);
    }
  };

  const requestCancel = () => {
    setConfirmingCancel(true);
    setMessage("Confirmation prompt: please confirm cancellation before we release your party size back to the slot availability.");
  };

  const confirmCancel = async () => {
    setCancelling(true);
    setMessage("Loading: cancelling reservation and restoring slot availability...");
    try {
      const updated = await cancelBooking({ reference: booking.reference, email: booking.email });
      setBooking(updated);
      setConfirmingCancel(false);
      setMessage("Cancellation success: reservation status changed to cancelled and the cancelled party size is released back into the slot availability on the booking page.");
    } catch (error) {
      setMessage(error.message || "Error: cancellation failed. Please retry with the same booking reference and email.");
    } finally {
      setCancelling(false);
    }
  };

  const partySize = booking ? Number(booking.adults) + Number(booking.children) : 0;

  return (
    <section className="mx-auto max-w-4xl">
      <div className="paper-panel relative overflow-hidden rounded-[2rem] p-8 sm:p-10">
        <div className="absolute bottom-0 left-0 top-0 w-3 bg-[radial-gradient(circle,hsl(var(--background))_35%,transparent_38%)] bg-[length:12px_18px]" aria-hidden="true" />
        <p className="text-sm font-bold uppercase tracking-[0.25em] text-primary">Booking lookup</p>
        <h1 className="mt-4 text-4xl font-semibold sm:text-5xl">Manage Booking</h1>
        <p className="mt-4 max-w-2xl leading-7 text-muted-foreground">Use the reference from your paper picking pass and the email used to book.</p>

        <form className="mt-8 grid gap-4 md:grid-cols-[1fr_1fr_auto] md:items-end" onSubmit={lookup}>
          <div className="grid gap-2">
            <Label htmlFor="lookup-reference">Booking reference</Label>
            <Input id="lookup-reference" value={reference} onChange={(event) => setReference(event.target.value)} placeholder="BBF-AB-1234" />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="lookup-email">Email</Label>
            <Input id="lookup-email" type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@example.com" />
          </div>
          <Button type="submit" disabled={loading} className="bg-primary text-primary-foreground"><Search className="mr-2 h-4 w-4" />{loading ? "Looking..." : "Look up"}</Button>
        </form>

        <p className="mt-4 rounded-2xl bg-background p-4 text-sm font-bold text-muted-foreground" aria-live="polite">{message}</p>

        {booking && (
          <div className="mt-8 rounded-[1.5rem] border border-dashed border-primary/40 bg-background p-5">
            <p className="text-sm font-black uppercase tracking-[0.2em] text-primary">Same reservation details after reload</p>
            <div className="mt-5 grid gap-4 sm:grid-cols-3">
              <div className="rounded-2xl bg-card p-4"><p className="text-xs font-bold uppercase text-muted-foreground">Reference</p><p className="mt-2 font-display text-2xl">{booking.reference}</p></div>
              <div className="rounded-2xl bg-card p-4"><p className="text-xs font-bold uppercase text-muted-foreground">Arrival</p><p className="mt-2 font-display text-2xl">{formatDate(booking.date)} {booking.startTime}</p></div>
              <div className="rounded-2xl bg-card p-4"><p className="text-xs font-bold uppercase text-muted-foreground">Party</p><p className="mt-2 font-display text-2xl">{partySize} pickers</p></div>
            </div>
            <dl className="mt-5 grid gap-3 text-sm sm:grid-cols-2">
              <div><dt className="font-bold text-muted-foreground">Visitor name</dt><dd>{booking.customerName}</dd></div>
              <div><dt className="font-bold text-muted-foreground">Email</dt><dd>{booking.email}</dd></div>
              <div><dt className="font-bold text-muted-foreground">Phone</dt><dd>{booking.phone}</dd></div>
              <div><dt className="font-bold text-muted-foreground">Booking status</dt><dd className="font-bold capitalize">{booking.status}</dd></div>
            </dl>
            {booking.status !== "cancelled" && !confirmingCancel && (
              <Button type="button" variant="outline" className="mt-6 border-destructive text-destructive hover:bg-destructive/10" onClick={requestCancel}>Cancel reservation</Button>
            )}
            {confirmingCancel && (
              <div className="mt-6 rounded-2xl border border-destructive/30 bg-destructive/10 p-4">
                <p className="text-sm font-bold text-destructive">Confirmation prompt asks you to confirm cancellation for {booking.reference}. This will release {partySize} places back into the slot.</p>
                <div className="mt-4 flex flex-col gap-3 sm:flex-row">
                  <Button type="button" onClick={confirmCancel} disabled={cancelling} className="bg-destructive text-destructive-foreground">{cancelling ? "Cancelling..." : "Confirm cancellation"}</Button>
                  <Button type="button" variant="outline" onClick={() => { setConfirmingCancel(false); setMessage("Cancellation prompt closed; booking remains active."); }} disabled={cancelling}>Keep reservation</Button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </section>
  );
}
